import{_ as s,o as i,c as o,m as a,e as l,k as r,w as n,f as c,l as d}from"./index-Dp7gseva.js";const u={},m={class:"min-h-screen pt-32 pb-20 px-6 max-w-4xl mx-auto text-white"},p={class:"mt-12 text-center"};function h(b,e){const t=d("router-link");return i(),o("div",m,[e[1]||(e[1]=a('<h1 class="text-4xl font-bold mb-8">Service Level Commitment</h1><div class="space-y-8 text-neutral-300 leading-relaxed"><div class="p-4 bg-blue-500/10 border border-blue-500/30 rounded-xl"><p class="text-blue-400 font-medium">This document outlines our service targets. These are goals we work towards, not contractual guarantees. For formal SLA agreements, please discuss with us directly.</p></div><section><h2 class="text-2xl font-bold text-white mb-4">1. Scope</h2><p>This Service Level Commitment applies to clients with active Managed IT Services (MSP) agreements. One-off repair or consulting services are not covered by this commitment.</p></section><section><h2 class="text-2xl font-bold text-white mb-4">2. Response Time Targets</h2><p class="mb-4">We aim to respond to support requests within the following timeframes:</p><div class="overflow-x-auto"><table class="w-full text-sm border border-neutral-700 rounded-lg overflow-hidden"><thead class="bg-neutral-800"><tr><th class="text-left p-3 font-semibold">Priority</th><th class="text-left p-3 font-semibold">Description</th><th class="text-left p-3 font-semibold">Response Target</th></tr></thead><tbody class="divide-y divide-neutral-700"><tr class="bg-neutral-900/50"><td class="p-3 font-medium text-red-400">Critical</td><td class="p-3">Complete business outage, security breach</td><td class="p-3">Within 2 hours</td></tr><tr class="bg-neutral-900/50"><td class="p-3 font-medium text-amber-400">High</td><td class="p-3">Major system degradation affecting multiple users</td><td class="p-3">Within 4 hours</td></tr><tr class="bg-neutral-900/50"><td class="p-3 font-medium text-blue-400">Medium</td><td class="p-3">Single user impacted, workaround available</td><td class="p-3">Within 8 hours</td></tr><tr class="bg-neutral-900/50"><td class="p-3 font-medium text-neutral-400">Low</td><td class="p-3">General enquiries, non-urgent requests</td><td class="p-3">Within 24 hours</td></tr></tbody></table></div><p class="text-sm text-neutral-500 mt-4">Response times are measured during business hours (Mon–Fri, 9am–5pm UK time). Response means acknowledgement of the issue, not necessarily resolution.</p></section><section><h2 class="text-2xl font-bold text-white mb-4">3. Availability Target</h2><p>For systems under our management, we aim for 99% uptime measured monthly. This target excludes:</p><ul class="list-disc list-inside space-y-2 mt-4"><li>Scheduled maintenance (notified in advance)</li><li>Third-party service outages beyond our control</li><li>Client-caused issues or unauthorized changes</li><li>Force majeure events</li></ul></section><section><h2 class="text-2xl font-bold text-white mb-4">4. Exclusions</h2><p>This commitment does not apply to:</p><ul class="list-disc list-inside space-y-2 mt-4"><li>Hardware failures (unless covered by a separate hardware support agreement)</li><li>Issues caused by software not supplied or approved by us</li><li>Internet connectivity issues at the client&#39;s premises</li><li>Cyberattacks originating from client devices or behaviour</li><li>Client failure to implement our security recommendations</li></ul></section><section><h2 class="text-2xl font-bold text-white mb-4">5. Remedies</h2><p>If we consistently fail to meet our service targets, we will work with you to identify root causes and implement improvements. This commitment does not create any right to service credits, refunds, or compensation unless separately agreed in writing.</p></section><section><h2 class="text-2xl font-bold text-white mb-4">6. Limitation of Liability</h2><p>Our liability for any failure to meet service targets is limited to the monthly fee paid for the affected service. We expressly exclude liability for any indirect, consequential, or economic losses, including but not limited to lost revenue, lost data, or business interruption.</p></section><p class="text-neutral-500 text-sm pt-8">Last updated: January 2026</p></div>',2)),l("div",p,[r(t,{to:"/",class:"text-neutral-500 hover:text-white transition-colors"},{default:n(()=>[...e[0]||(e[0]=[c("← Back to Home",-1)])]),_:1})])])}const x=s(u,[["render",h]]);export{x as default};
